    "css": ".loader {\n  position: relative;\n  transform: scale(2);\n  border-radius: 50%;\n  border: 1px solid;\n  width: 30px;\n  height: 30px;\n  color: white;\n}\n\n.loader::after {\n  position: absolute;\n  width: 0px;\n  height: 10px;\n  display: block;\n  border-left: 1px solid #fff;\n  content: '';\n  left: 14px;\n  border-radius: 1px;\n  top: 4px;\n  animation-duration: 1s;\n}\n\n.loader::before {\n  position: absolute;\n  width: 0px;\n  height: 10px;\n  display: block;\n  border-left: 1px solid #fff;\n  content: '';\n  left: 14px;\n  border-radius: 1px;\n  top: 4px;\n  animation-duration: 40s;\n}\n\n.loader::before,.loader::after {\n  transform-origin: bottom;\n  animation-name: dial;\n  animation-iteration-count: infinite;\n  animation-timing-function: linear;\n}\n\n@keyframes dial {\n  0% {\n    transform: rotate(0deg);\n  }\n\n  100% {\n    transform: rotate(360deg);\n  }\n}"
