    "css": ".heart #line {\n  fill: none;\n  stroke: #e00000;\n  stroke-width: 1.5;\n  stroke-linecap: butt;\n  stroke-linejoin: round;\n  stroke-miterlimit: 4;\n  stroke-opacity: 1;\n  stroke-dasharray: 1;\n  stroke-dashoffset: 1;\n  animation: dash 3s linear infinite;\n}\n.heart #point {\n  fill: none;\n  stroke: #f00000;\n  stroke-width: 5;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n  stroke-miterlimit: 0.1;\n  stroke-opacity: 1;\n  stroke-dasharray: 0.0001, 0.9999;\n  stroke-dashoffset: 1;\n  animation: dash 3s linear infinite;\n}\n@keyframes dash {\n  0% {\n    stroke-dashoffset: 1;\n  }\n  80% {\n    stroke-dashoffset: 0;\n  }\n  100% {\n    stroke-dashoffset: 0;\n  }\n}\n"
