    "css": ".eye-lid {\n  background-color: rgb(0, 0, 0);\n  border-radius: 50%;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  box-shadow: 0 9px 0 2px rgba(0, 0, 0, 0.2);\n  width: 150px;\n  height: 150px;\n}\n\n.eye {\n  background-color: #ffbc03;\n  border-radius: 50%;\n  transform: translate3d(0, 0, 0) rotate(90deg);\n  width: 120px;\n  height: 120px;\n  animation: eye 5s infinite;\n}\n\n@keyframes eye {\n  12%,\n  25% {\n    width: 100px;\n    height: 110px;\n  }\n\n  37%, \n  50% {\n    width: 60px;\n    height: 130px;\n  }\n\n  63%, \n  75% {\n    width: 100px;\n    height: 103px;\n  }\n\n  87% {\n    width: 100px;\n    height: 100px;\n  }\n}\n\n.cornea {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  background-color: rgb(0, 0, 0);\n  border-radius: 50%;\n  width: 50px;\n  height: 50px;\n  animation: eye-color 5s infinite;\n}\n\n@keyframes eye-color {\n  63%, 75% {\n    background-color: rgb(8, 20, 96);\n  }\n}\n\n.white-pupil {\n  position: absolute;\n  top: 9%;\n  left: 10%;\n  border-radius: 50%;\n  background-color: #ffbc03;\n  width: 20px;\n  height: 20px;\n}"
