    "css": ".loader {\n  width: 12em;\n  height: 3em;\n  position: relative;\n  overflow: hidden;\n  border-bottom: 8px solid #000;\n  filter: url(#goo);\n}\n\n.loader::before {\n  content: '';\n  width: 22em;\n  height: 18em;\n  background: #f00;\n  position: absolute;\n  border-radius: 50%;\n  left: -2em;\n  bottom: -18em;\n  animation: wee1 2s linear infinite;\n}\n\n.loader::after {\n  content: '';\n  width: 16em;\n  height: 12em;\n  background: #0ff;\n  position: absolute;\n  border-radius: 50%;\n  left: -4em;\n  bottom: -12em;\n  animation: wee2 2s linear infinite 0.75s;\n}\n\n@keyframes wee1 {\n  0% {\n    transform: translateX(-10em) rotate(0deg);\n  }\n\n  100% {\n    transform: translateX(7em) rotate(180deg);\n  }\n}\n\n@keyframes wee2 {\n  0% {\n    transform: translateX(-8em) rotate(0deg);\n  }\n\n  100% {\n    transform: translateX(8em) rotate(180deg);\n  }\n}"
