    "css": ".loader {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n}\n\n.heading {\n  color: black;\n  letter-spacing: 0.2em;\n  margin-bottom: 1em;\n}\n\n.loading {\n  display: flex;\n  width: 5em;\n  align-items: center;\n  justify-content: center;\n}\n\n.load {\n  width: 23px;\n  height: 3px;\n  background-color: limegreen;\n  animation: 1s move_5011 infinite;\n  border-radius: 5px;\n  margin: 0.1em;\n}\n\n.load:nth-child(1) {\n  animation-delay: 0.2s;\n}\n\n.load:nth-child(2) {\n  animation-delay: 0.4s;\n}\n\n.load:nth-child(3) {\n  animation-delay: 0.6s;\n}\n\n@keyframes move_5011 {\n  0% {\n    width: 0.2em;\n  }\n\n  25% {\n    width: 0.7em;\n  }\n\n  50% {\n    width: 1.5em;\n  }\n\n  100% {\n    width: 0.2em;\n  }\n}"
