    "css": ".loading {\n  transform: translate(0%, -50%);\n}\n\n.l {\n  color: black;\n  opacity: 0;\n  animation: op 2s ease-in-out infinite;\n  animation-delay: 0.2s;\n}\n\n.o {\n  color: black;\n  opacity: 0;\n  animation: op 2s ease-in-out infinite;\n  animation-delay: 0.4s;\n}\n\n.a {\n  color: black;\n  opacity: 0;\n  animation: op 2s ease-in-out infinite;\n  animation-delay: 0.6s;\n}\n\n.d {\n  color: black;\n  opacity: 0;\n  animation: op 2s ease-in-out infinite;\n  animation-delay: 0.8s;\n}\n\n.i {\n  color: black;\n  opacity: 0;\n  animation: op 2s ease-in-out infinite;\n  animation-delay: 1s;\n}\n\n.n {\n  color: black;\n  opacity: 0;\n  animation: op 2s ease-in-out infinite;\n  animation-delay: 1.2s;\n}\n\n.g {\n  color: black;\n  opacity: 0;\n  animation: op 2s ease-in-out infinite;\n  animation-delay: 1.4s;\n}\n\n.d1 {\n  color: black;\n  opacity: 0;\n  animation: op1 2s ease-in-out infinite;\n  animation-delay: 1.6s;\n}\n\n.d2 {\n  color: black;\n  opacity: 0;\n  animation: op1 2s ease-in-out infinite;\n  animation-delay: 2s;\n}\n\n.load {\n  position: relative;\n  width: 1.2em;\n  height: 1.2em;\n  border-radius: 50%;\n}\n\n.progress {\n  top: 50%;\n  left: -80%;\n  position: absolute;\n  margin-top: 2.2em;\n  transform: translate(10%, -50%);\n  content: '';\n  width: 3.1em;\n  height: 3.1em;\n  background: transparent;\n  border-radius: 50%;\n  animation: load_37100 2s ease-in-out infinite;\n  animation-delay: 1s;\n}\n\n@keyframes load_37100 {\n  0% {\n    background-color: #DB4437;\n  }\n\n  25% {\n    background-color: #F4B400;\n  }\n\n  75% {\n    background-color: #0F9D58;\n  }\n\n  100% {\n    background-color: #4285F4;\n  }\n}\n\n.progress:nth-child(2) {\n  left: 50%;\n  animation-delay: 1.3s;\n}\n\n.progress:nth-child(3) {\n  left: 180%;\n  animation-delay: 1.7s;\n}\n\n.progress:nth-child(4) {\n  left: 300%;\n  animation-delay: 2s;\n}\n\n@keyframes op {\n  0% {\n    color: black;\n    opacity: 1;\n  }\n\n  50% {\n    color: green;\n    opacity: 1;\n  }\n\n  100% {\n    color: black;\n    opacity: 1;\n  }\n}\n\n@keyframes op1 {\n  0% {\n    color: black;\n    opacity: 1;\n  }\n\n  50% {\n    color: green;\n    opacity: 0;\n  }\n\n  100% {\n    color: black;\n    opacity: 1;\n  }\n}"
