    "css": ".anim-box {\n  width: 200px;\n  height: 200px;\n  border: 5px solid #333;\n  margin: 100px auto;\n  position: relative;\n}\n\n.anim-interieur {\n  width: 100px;\n  height: 50px;\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n    /* background-color: orange; */\n  text-align: center;\n}\n\n.rect {\n  background-color: #333;\n  display: inline-block;\n  height: 60px;\n  width: 6px;\n  margin: 0px  1px;\n  animation: etire 1.2s infinite ease-in-out;\n}\n\n@keyframes etire {\n  0% {\n    transform: scaleY(0.4);\n  }\n\n  20% {\n    transform: scaleY(1);\n  }\n\n  40% {\n    transform: scaleY(0.4);\n  }\n\n  100% {\n    transform: scaleY(0.4);\n  }\n}\n\n.rect2 {\n  animation-delay: -1.1s;\n}\n\n.rect3 {\n  animation-delay: -1s;\n}\n\n.rect4 {\n  animation-delay: -0.9s;\n}\n\n.rect5 {\n  animation-delay: -0.8s;\n}"
